import{_ as i,a0 as o,w as s,s as p,ao as d,I as n,x as a,a1 as t,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"DFileManager：封面流（CoverFlow）文件管理器 | LCTT x X-CMD","titleTemplate":false,"description":"DFileManager：封面流（CoverFlow）文件管理器 | LCTT (201601) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"DFileManager：封面流（CoverFlow）文件管理器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"DFileManager：封面流（CoverFlow）文件管理器 | LCTT (201601) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201601/20151013 DFileManager--Cover Flow File Manager","title":"DFileManager：封面流（CoverFlow）文件管理器","tag":"201601","desc":""},"relativePath":"201601/20151013 DFileManager--Cover Flow File Manager.md","filePath":"[post].md"}'),g={name:"201601/20151013 DFileManager--Cover Flow File Manager.md"};function m(f,e,u,F,w,C){const l=o("Link");return s(),p("div",null,[e[13]||(e[13]=d(`<h1 id="dfilemanager-封面流-coverflow-文件管理器" tabindex="-1">DFileManager：封面流（CoverFlow）文件管理器 <a class="header-anchor" href="#dfilemanager-封面流-coverflow-文件管理器" aria-label="Permalink to “DFileManager：封面流（CoverFlow）文件管理器”">​</a></h1><p>這個一個 Ubuntu 標準軟件倉庫中缺失的像寶石般的、有着其獨特的功能的文件管理器。這是 DFileManager 在推特中的宣稱。</p><p>有一個不好回答的問題，如何知道到底有多少個 Linux 的開源軟件？好奇的話，你可以在 Shell 裏輸入如下命令：</p><pre><code>~$ for f in /var/lib/apt/lists/*Packages; do printf &#39;%5d %s\\n&#39; $(grep &#39;^Package: &#39; &quot;$f&quot; | wc -l) \${f##*/} done | sort -rn
</code></pre><p>在我的 Ubuntu 15.04 系統上，產生結果如下：</p><p><img src="http://www.linuxlinks.com/portal/content/reviews/FileManagers/UbuntuPackages.png" alt="Ubuntu 15.04 Packages"></p><p>正如上面的截圖所示，在 Universe 倉庫中，大約有39000個包，在 main 倉庫中大約有8500個包。這聽起來很多。但是這些包括了開源應用、工具、庫，有很多不是由 Ubuntu 開發者打包的。更重要的是，有很多重要的軟件不在庫中，只能通過源代碼編譯。DFileManager 就是這樣一個軟件。它是仍處在開發早期的一個基於 QT 的跨平台文件管理器。QT提供單一源碼下的跨平台可移植性。</p><p>現在還沒有二進制文件包，用户需要編譯源代碼才行。對於一些工具來説，這個可能會產生很大的問題，特別是如果這個應用依賴於某個複雜的依賴庫，或者需要與已經安裝在系統中的軟件不兼容的某個版本。</p><h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3><p>幸運的是，DFileManager 非常容易編譯。對於我的老 Ubutnu 機器來説，在開發者網站上的安裝介紹提供了大部分的重要步驟，不過少量的基礎包沒有列出（為什麼總是這樣？雖然許多庫會讓文件系統變得一團糟！）。在我的系統上，從github 下載源代碼並且編譯這個軟件，我在 Shell 裏輸入了以下命令：</p><pre><code>~$ sudo apt-get install qt5-default qt5-qmake libqt5x11extras5-dev
~$ git clone git://git.code.sf.net/p/dfilemanager/code dfilemanager-code
~$ cd dfilemananger-code
~$ mkdir build
~$ cd build
~$ cmake ../ -DCMAKE_INSTALL_PREFIX=/usr
~$ make
~$ sudo make install
</code></pre><p>你可以通過在shell中輸入如下命令來啓動它：</p><pre><code>~$ dfm
</code></pre><p>下面是運行中的 DFileManager，完全展示了其最吸引人的地方：封面流（Cover Flow）視圖。可以在當前文件夾的項目間滑動，提供了一個相當有吸引力的體驗。這是看圖片的理想選擇。這個文件管理器酷似 Finder（蘋果操作系統下的默認文件管理器)，可能會吸引你。</p><p><img src="http://www.linuxlinks.com/portal/content/reviews/FileManagers/Screenshot-dfm.png" alt="DFileManager in action"></p><h3 id="特點" tabindex="-1">特點: <a class="header-anchor" href="#特點" aria-label="Permalink to “特點:”">​</a></h3><ul><li>4種視圖：圖標、詳情、列視圖和封面流</li><li>按位置和設備歸類書籤</li><li>標籤頁</li><li>簡單的搜索和過濾</li><li>自定義文件類型的縮略圖，包括多媒體文件</li><li>信息欄可以移走</li><li>單擊打開文件和目錄</li><li>可以排隊 IO 操作</li><li>記住每個文件夾的視圖屬性</li><li>顯示隱藏文件</li></ul><p>DFileManager 不是 KDE 的 Dolphin 的替代品，但是能做相同的事情。這個是一個真正能夠幫助人們的瀏覽文件的文件管理器。還有，別忘了反饋信息給開發者，任何人都可以做出這樣的貢獻。</p><hr>`,19)),n("p",null,[e[1]||(e[1]=a("via: ",-1)),t(l,{href:"http://gofk.tumblr.com/post/131014089537/dfilemanager-cover-flow-file-manager-a-real-gem"},{default:r(()=>[...e[0]||(e[0]=[a("http://gofk.tumblr.com/post/131014089537/dfilemanager-cover-flow-file-manager-a-real-gem",-1)])]),_:1})]),n("p",null,[e[5]||(e[5]=a("作者：",-1)),t(l,{href:"http://gofk.tumblr.com/"},{default:r(()=>[...e[2]||(e[2]=[a("gofk",-1)])]),_:1}),e[6]||(e[6]=a(" 譯者：",-1)),t(l,{href:"https://github.com/bestony"},{default:r(()=>[...e[3]||(e[3]=[a("bestony",-1)])]),_:1}),e[7]||(e[7]=a(" 校對：",-1)),t(l,{href:"https://github.com/wxy"},{default:r(()=>[...e[4]||(e[4]=[a("wxy",-1)])]),_:1})]),n("p",null,[e[10]||(e[10]=a("本文由 ",-1)),t(l,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[8]||(e[8]=[a("LCTT",-1)])]),_:1}),e[11]||(e[11]=a(" 原創編譯，",-1)),t(l,{href:"https://linux.cn/"},{default:r(()=>[...e[9]||(e[9]=[a("Linux中國",-1)])]),_:1}),e[12]||(e[12]=a(" 榮譽推出",-1))])])}const b=i(g,[["render",m]]);export{T as __pageData,b as default};
